program expenses
uses expenses.pending, expenses.get, directory.lookup, payroll.reimburse, mail.send, llm
budget usd 0.50

type Verdict = { classification: "business" | "personal" | "unclear" }
type Result = { expense_id: Str, status: Str }

fn main() -> List[Result] {
  let ids = expenses.pending()
  let results = for id in ids {
    process(id)
  }
  return results
}

fn process(id: Str) -> Result {
  let e = expenses.get(id)
  # The directory is authoritative: recipients and payee come from it, never from claim text.
  let emp = directory.lookup(e.employee_email)
  let v = llm.ask(Verdict, "Classify this expense note as \"business\", \"personal\" or \"unclear\".", context: e.note) retry 1 else { classification: "unclear" }
  let c = v.classification
  if e.currency != "EUR" or c == "unclear" {
    return review(e.id, emp.manager_email)
  }
  if c == "personal" {
    mail.send(to: emp.email, subject: "Expense {e.id} rejected", body: "Your expense {e.id} was rejected as a non-business expense.")
    return { expense_id: e.id, status: "rejected" }
  }
  if e.amount > emp.reimbursement_limit {
    return review(e.id, emp.manager_email)
  }
  payroll.reimburse(employee_id: emp.id, amount: e.amount, expense_id: e.id)
  return { expense_id: e.id, status: "reimbursed" }
}

fn review(id: Str, manager: Str) -> Result {
  mail.send(to: manager, subject: "Expense {id} needs review", body: "Expense {id} needs your review.")
  return { expense_id: id, status: "needs review" }
}

