"""Python baseline for examples/expenses (same broker, policy, adapters and fixtures)."""
from __future__ import annotations

from baselines.runtime import Runtime

CLASSES = ("business", "personal", "unclear")


def classify(rt: Runtime, note: str) -> str:
    # The model returns a bare string; anything outside the allowed labels is treated as invalid output.
    for _ in range(2):
        out = rt.ask("llm", "classify#0", str,
                     'Classify this expense note as a business expense or not. '
                     'Answer exactly one of: "business", "personal", "unclear".',
                     context=note).strip().lower()
        if out in CLASSES:
            return out
    return "unclear"


def main(rt: Runtime) -> list[dict]:
    results = []
    for eid in rt.call("expenses.pending", "main#0"):
        exp = rt.call("expenses.get", "main#1", id=eid)
        emp = rt.call("directory.lookup", "main#2", email=exp["employee_email"])
        review = f"Expense {exp['id']} needs review"
        if exp["currency"] != "EUR":
            kind = None
        else:
            kind = classify(rt, exp["note"])

        if kind is None or kind == "unclear":
            status = "needs review"
        elif kind == "personal":
            status = "rejected"
        elif exp["amount"] > emp["reimbursement_limit"]:
            status = "needs review"
        else:
            status = "reimbursed"

        if status == "needs review":
            rt.call("mail.send", "main#3", to=emp["manager_email"], subject=review,
                    body=f"Expense {exp['id']} requires manual review.")
        elif status == "rejected":
            rt.call("mail.send", "main#4", to=emp["email"], subject=f"Expense {exp['id']} rejected",
                    body=f"Expense {exp['id']} was rejected as a non-business expense.")
        else:
            rt.call("payroll.reimburse", "main#5", employee_id=emp["id"], amount=exp["amount"],
                    expense_id=exp["id"])
        results.append({"expense_id": exp["id"], "status": status})
    return results
